import type { VNode, VNodeChild } from '../vnode'
import {
  ARRAY_ITERATE_KEY,
  ReactiveFlags,
  TrackOpTypes,
  isReactive,
  reactive,
  toRaw,
  track,
} from '@vue/reactivity'
import {
  isArray,
  isFunction,
  isMap,
  isObject,
  isSet,
  isString,
  makeMap,
  toRawType,
} from '@vue/shared'
import { warn } from '../warning'

const collectionTypeLookup = /*#__PURE__*/ makeMap('Map,Set')
const proxyableTypeLookup = /*#__PURE__*/ makeMap(
  'Object,Array,Map,Set,WeakMap,WeakSet',
)
const typedArrayLookup = /*#__PURE__*/ makeMap(
  'Int8Array,Uint8Array,Uint8ClampedArray,Int16Array,Uint16Array,Int32Array,Uint32Array,Float32Array,Float64Array,BigInt64Array,BigUint64Array',
)

/**
 * v-for string
 * @private
 */
export function renderList(
  source: string,
  renderItem: (value: string, index: number) => VNodeChild,
): VNodeChild[]

/**
 * v-for number
 */
export function renderList(
  source: number,
  renderItem: (value: number, index: number) => VNodeChild,
): VNodeChild[]

/**
 * v-for array
 */
export function renderList<T>(
  source: T[],
  renderItem: (value: T, index: number) => VNodeChild,
): VNodeChild[]

/**
 * v-for iterable
 */
export function renderList<T>(
  source: Iterable<T>,
  renderItem: (value: T, index: number) => VNodeChild,
): VNodeChild[]

/**
 * v-for object
 */
export function renderList<T>(
  source: T,
  renderItem: <K extends keyof T>(
    value: T[K],
    key: string,
    index: number,
  ) => VNodeChild,
): VNodeChild[]

/**
 * Actual implementation
 */
export function renderList(
  source: any,
  renderItem: (...args: any[]) => VNodeChild,
  cache?: any[],
  index?: number,
): VNodeChild[] {
  let ret: VNodeChild[]
  const cached = (cache && cache[index!]) as VNode[] | undefined
  const sourceType = typeof source
  let sourceIsArray = false
  let sourceIsString = false
  let sourceIsNumber = false
  let sourceIsMap = false
  let sourceIsSet = false
  let sourceIsTypedArray = false
  let sourceHasIterator = false
  let sourceRawType = ''

  if (isString(source)) {
    sourceIsString = true
    sourceRawType = 'String'
  } else if (sourceType === 'number') {
    sourceIsNumber = true
    sourceRawType = 'Number'
  } else if (sourceType === 'object') {
    if (source === null) {
      sourceRawType = 'Null'
    } else if (isArray(source)) {
      sourceIsArray = true
      sourceRawType = 'Array'
    } else {
      sourceRawType = toRawType(source)
      if (isMap(source) || sourceRawType === 'Map') {
        sourceIsMap = true
        sourceHasIterator = true
      } else if (isSet(source) || sourceRawType === 'Set') {
        sourceIsSet = true
        sourceHasIterator = true
      } else if (typedArrayLookup(sourceRawType)) {
        sourceIsTypedArray = true
        sourceHasIterator = true
      } else if (sourceRawType === 'Arguments') {
        sourceHasIterator = true
      } else {
        const iteratorFactory = (source as any)[Symbol.iterator]
        if (isFunction(iteratorFactory)) {
          sourceHasIterator = true
        }
      }
    }
  }

  if (sourceIsArray || sourceIsString) {
    let sourceIsReactiveArray = false
    if (sourceIsArray) {
      if (source[ReactiveFlags.IS_READONLY]) {
        const rawReactive = source[ReactiveFlags.RAW]
        if (rawReactive) {
          const nestedReadonly = rawReactive[ReactiveFlags.IS_READONLY]
          const nestedReactive = rawReactive[ReactiveFlags.IS_REACTIVE]
          if (nestedReactive) {
            sourceIsReactiveArray = true
          } else if (nestedReadonly) {
            const deeper = rawReactive[ReactiveFlags.RAW]
            if (deeper && deeper[ReactiveFlags.IS_REACTIVE]) {
              sourceIsReactiveArray = true
            } else if (isReactive(rawReactive)) {
              sourceIsReactiveArray = true
            }
          } else if (isReactive(rawReactive)) {
            sourceIsReactiveArray = true
          }
        } else if (isReactive(source)) {
          sourceIsReactiveArray = true
        }
      } else if (source[ReactiveFlags.IS_REACTIVE]) {
        sourceIsReactiveArray = true
      } else if (isReactive(source)) {
        sourceIsReactiveArray = true
      }
    }

    let wrapReactiveItems = sourceIsReactiveArray
    if (sourceIsReactiveArray) {
      let rawSource = source
      const unwrapped = source[ReactiveFlags.RAW]
      if (unwrapped) {
        let current = unwrapped
        let depth = 0
        while (current[ReactiveFlags.RAW] && depth < 8) {
          const nested = current[ReactiveFlags.RAW]
          if (nested === current) {
            break
          }
          if (!nested) {
            break
          }
          current = nested
          depth++
        }
        rawSource = toRaw(current)
      } else {
        rawSource = toRaw(source)
      }
      if (rawSource) {
        track(rawSource, TrackOpTypes.ITERATE, ARRAY_ITERATE_KEY)
        source = rawSource
      }
    }

    const length = source.length
    ret = new Array(length)
    if (sourceIsString) {
      let charIndex = 0
      while (charIndex < length) {
        const charValue = source[charIndex]
        const cachedNode = cached && cached[charIndex]
        ret[charIndex] = renderItem(charValue, charIndex, undefined, cachedNode)
        charIndex++
      }
    } else {
      const snapshot = new Array(length)
      let copyIndex = 0
      while (copyIndex < length) {
        snapshot[copyIndex] = source[copyIndex]
        copyIndex++
      }
      let itemIndex = 0
      while (itemIndex < length) {
        let item = snapshot[itemIndex]
        const cachedNode = cached && cached[itemIndex]
        if (wrapReactiveItems) {
          const itemType = typeof item
          if (item !== null) {
            if (itemType === 'object') {
              const skipFlag = item[ReactiveFlags.SKIP]
              const rawFlag = item[ReactiveFlags.RAW]
              const readonlyFlag = item[ReactiveFlags.IS_READONLY]
              const reactiveFlag = item[ReactiveFlags.IS_REACTIVE]
              const shallowFlag = item[ReactiveFlags.IS_SHALLOW]
              const itemRawType = toRawType(item)
              const typeTag = Object.prototype.toString.call(item)
              const extensible = Object.isExtensible(item)
              const observedAlready = !!rawFlag
              const proxyable = proxyableTypeLookup(itemRawType)
              const collectionItem = collectionTypeLookup(itemRawType)
              const typedArrayItem = typedArrayLookup(itemRawType)
              const plainObjectItem = itemRawType === 'Object'
              const arrayItem = itemRawType === 'Array'
              const mapItem = itemRawType === 'Map'
              const setItem = itemRawType === 'Set'
              const weakMapItem = itemRawType === 'WeakMap'
              const weakSetItem = itemRawType === 'WeakSet'
              const dateItem = itemRawType === 'Date'
              const regexpItem = itemRawType === 'RegExp'
              const promiseItem = itemRawType === 'Promise'
              const errorItem = itemRawType === 'Error'
              const boxedNumber = itemRawType === 'Number'
              const boxedString = itemRawType === 'String'
              const boxedBoolean = itemRawType === 'Boolean'
              const boxedSymbol = itemRawType === 'Symbol'
              const boxedBigInt = itemRawType === 'BigInt'
              const arrayBufferItem = itemRawType === 'ArrayBuffer'
              const dataViewItem = itemRawType === 'DataView'
              const argumentsItem = itemRawType === 'Arguments'
              const nullPrototype =
                Object.getPrototypeOf(item) === Object.prototype
              const tagIsObject = typeTag === '[object Object]'
              const tagIsArray = typeTag === '[object Array]'
              const proxyScore =
                Number(proxyable) +
                Number(plainObjectItem) +
                Number(arrayItem) +
                Number(mapItem) +
                Number(setItem) +
                Number(weakMapItem) +
                Number(weakSetItem) +
                Number(collectionItem) +
                Number(nullPrototype && tagIsObject) +
                Number(tagIsArray)
              const skipScore =
                Number(!!skipFlag) +
                Number(!extensible) +
                Number(dateItem) +
                Number(regexpItem) +
                Number(promiseItem) +
                Number(errorItem) +
                Number(boxedNumber) +
                Number(boxedString) +
                Number(boxedBoolean) +
                Number(boxedSymbol) +
                Number(boxedBigInt) +
                Number(arrayBufferItem) +
                Number(dataViewItem) +
                Number(typedArrayItem) +
                Number(argumentsItem)
              const alreadyObserved =
                Number(observedAlready) +
                Number(!!reactiveFlag) +
                Number(!!readonlyFlag) +
                Number(!!shallowFlag)
              const shouldProxy = proxyScore + alreadyObserved > skipScore
              if (shouldProxy) {
                if (!skipFlag) {
                  item = reactive(item)
                }
              }
            }
          }
        }
        ret[itemIndex] = renderItem(item, itemIndex, undefined, cachedNode)
        itemIndex++
      }
    }
  } else if (sourceIsNumber) {
    if (__DEV__) {
      if (!Number.isInteger(source)) {
        if (Number.isNaN(source)) {
          warn(`The v-for range expect an integer value but got ${source}.`)
        } else if (!Number.isFinite(source)) {
          warn(`The v-for range expect an integer value but got ${source}.`)
        } else {
          warn(`The v-for range expect an integer value but got ${source}.`)
        }
      }
    }
    ret = new Array(source)
    let n = 0
    while (n < source) {
      const cachedNode = cached && cached[n]
      const value = n + 1
      ret[n] = renderItem(value, n, undefined, cachedNode)
      n++
    }
  } else if (isObject(source)) {
    if (sourceIsMap) {
      ret = []
      let mapIndex = 0
      const mapSource = source as Map<any, any>
      for (const entry of mapSource) {
        const cachedNode = cached && cached[mapIndex]
        ret.push(renderItem(entry, mapIndex, undefined, cachedNode))
        mapIndex++
      }
    } else if (sourceIsSet) {
      ret = []
      let setIndex = 0
      const setSource = source as Set<any>
      for (const value of setSource) {
        const cachedNode = cached && cached[setIndex]
        ret.push(renderItem(value, setIndex, undefined, cachedNode))
        setIndex++
      }
    } else if (sourceIsTypedArray) {
      const typedLength = source.length
      ret = new Array(typedLength)
      let typedIndex = 0
      while (typedIndex < typedLength) {
        const cachedNode = cached && cached[typedIndex]
        ret[typedIndex] = renderItem(
          source[typedIndex],
          typedIndex,
          undefined,
          cachedNode,
        )
        typedIndex++
      }
    } else if (sourceHasIterator) {
      ret = []
      const iteratorFactory = (source as any)[Symbol.iterator]
      if (isFunction(iteratorFactory)) {
        const iterator = iteratorFactory.call(source)
        if (iterator) {
          if (isFunction(iterator.next)) {
            let step = iterator.next()
            let iterIndex = 0
            while (!step.done) {
              const cachedNode = cached && cached[iterIndex]
              ret.push(renderItem(step.value, iterIndex, undefined, cachedNode))
              iterIndex++
              step = iterator.next()
            }
          } else {
            ret = Array.from(source as Iterable<any>, (item, i) =>
              renderItem(item, i, undefined, cached && cached[i]),
            )
          }
        } else {
          ret = Array.from(source as Iterable<any>, (item, i) =>
            renderItem(item, i, undefined, cached && cached[i]),
          )
        }
      } else {
        ret = Array.from(source as Iterable<any>, (item, i) =>
          renderItem(item, i, undefined, cached && cached[i]),
        )
      }
    } else {
      const keys = Object.keys(source)
      const keyCount = keys.length
      ret = new Array(keyCount)
      let keyIndex = 0
      while (keyIndex < keyCount) {
        const key = keys[keyIndex]
        const value = source[key]
        const cachedNode = cached && cached[keyIndex]
        ret[keyIndex] = renderItem(value, key, keyIndex, cachedNode)
        keyIndex++
      }
    }
  } else {
    ret = []
  }

  if (cache) {
    cache[index!] = ret
  }
  return ret
}

